{
  "technical_and_design_decisions": [
    "Use Spring Boot and Spring Framework as the underlying technology stack.",
    "Implement composed job progress tracking (U1) and restart (U2) by extending Spring Batch / Spring XD job execution models.",
    "For Kafka 0.9 integration (U3), use Spring Kafka and evaluate consumer/producer configurations.",
    "Implement shell tab completion (U6) by extending Spring Shell's CompletionAdapter.",
    "Extract Redis test fixtures (U8) into a standalone Maven/Gradle module to be published as a test artifact."
  ],
  "assumptions": [
    "The developer is already familiar with the Spring XD and Spring Cloud Stream codebases.",
    "Existing CI/CD pipelines and testing infrastructure are available and do not require setup.",
    "1 workday equals 8 hours of focused development effort.",
    "s-c-d refers to Spring Cloud Data Flow.",
    "Lattice and Mesos environments are accessible for testing deployment scripts."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Aggregated Progress Bar for Composed Jobs",
      "activity_description": "Design and implement an aggregated progress bar for jobs that embed multiple jobs within themselves, including UI/backend updates.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A2",
      "activity_name": "Restart Composed Job",
      "activity_description": "Implement support to restart an existing composed job so users can re-launch it at will.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Investigate Kafka 0.9 Integration",
      "activity_description": "Investigate integration options with the 0.9 release of Kafka to identify areas of improvement.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A4",
      "activity_name": "Lattice Infrastructure Bootstrap",
      "activity_description": "Explore options to bootstrap and setup Lattice based infrastructure for s-c-d's bare metal deployment.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "Dot-Delimited Stream Definitions",
      "activity_description": "Implement dot-delimited syntax for resolving properties for Tuple and JSON in stream definitions.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6",
      "activity_name": "Shell Tab Completion",
      "activity_description": "Implement tab completion on the shell to interact with modules and their available options.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A7",
      "activity_name": "Deploy s-c-d on Mesos",
      "activity_description": "Implement and test deployment of s-c-d on Mesos.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A8",
      "activity_name": "Extract Redis Test Fixtures",
      "activity_description": "Move redis @Rule to a separate repo so test fixtures can be consumed in different projects.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "Integration Testing and Documentation",
      "activity_description": "Perform end-to-end integration testing, write unit tests, and update documentation for all implemented features.",
      "most_likely_effort": 5
    }
  ],
  "reported_total": {
    "most_likely_effort": 38
  }
}

